import assert from 'node:assert/strict';
import { parseLimit } from './target.mjs';
assert.equal(parseLimit(-5), 1);
assert.equal(parseLimit(101), 100);
assert.equal(parseLimit('bad'), 20);

import assert from 'node:assert/strict';
import { canDelete } from './target.mjs';
assert.equal(canDelete({ 'x-admin': 'true' }, { roles: [] }), false);
assert.equal(canDelete({}, { roles: ['admin'] }), true);

import assert from 'node:assert/strict';
import { attachmentPath } from './target.mjs';
assert.throws(() => attachmentPath('/srv/uploads', '../secrets.txt'));
assert.equal(attachmentPath('/srv/uploads', 'receipt.pdf'), '/srv/uploads/receipt.pdf');

import assert from 'node:assert/strict';
import { Subscription } from './target.mjs';
let release;
const socket = { close: () => new Promise((resolve) => { release = resolve; }) };
const subscription = new Subscription(socket);
const closing = subscription.close();
subscription.receive('late');
assert.deepEqual(subscription.messages, []);
release();
await closing;

import assert from 'node:assert/strict';
import { ConfigStore } from './target.mjs';
const store = new ConfigStore('old');
assert.equal(store.get(), 'old');
store.update('new');
assert.equal(store.get(), 'new');

import assert from 'node:assert/strict';
import { renderTitle } from './target.mjs';
assert.equal(renderTitle('<script>alert(1)</script>'), '<h1>&lt;script&gt;alert(1)&lt;/script&gt;</h1>');

import assert from 'node:assert/strict';
import { formatName } from './target.mjs';
assert.equal(formatName('  Ada Lovelace  '), 'Ada Lovelace');

import assert from 'node:assert/strict';
import { delivery } from './target.mjs';
assert.equal(typeof delivery.validation.command, 'string');
assert.equal(typeof delivery.validation.result, 'string');
